<?php
namespace App\Http\Controllers;use App\Models\{Supplier,SupplierInvoice,SupplierPayment};use App\Services\SupplierPaymentService;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class PayableController extends Controller{public function index(Request $r){$c=$r->user()->company_id;return view('payables.index',['invoices'=>SupplierInvoice::with(['supplier','grn'])->where('company_id',$c)->latest('invoice_date')->paginate(20),'suppliers'=>Supplier::where('company_id',$c)->where('is_active',1)->orderBy('name')->get()]);}public function create(Request $r){$c=$r->user()->company_id;$suppliers=Supplier::where('company_id',$c)->where('is_active',1)->orderBy('name')->get();$invoiceId=$r->integer('invoice_id');$selectedInvoice=$invoiceId?SupplierInvoice::where('company_id',$c)->where('balance_amount','>',0)->findOrFail($invoiceId):null;$supplierId=$selectedInvoice?->supplier_id?:$r->integer('supplier_id');$invoices=$supplierId?SupplierInvoice::where('company_id',$c)->where('supplier_id',$supplierId)->where('balance_amount','>',0)->oldest('due_date')->get():collect();return view('payables.payment',compact('suppliers','supplierId','invoices','invoiceId','selectedInvoice'));}public function store(Request $r,SupplierPaymentService $service){$c=$r->user()->company_id;$data=$r->validate(['supplier_id'=>['required',Rule::exists('suppliers','id')->where(fn($q)=>$q->where('company_id',$c))],'payment_date'=>['required','date'],'payment_method'=>['required',Rule::in(['cash','cheque','bank_transfer','online_payment'])],'amount'=>['required','numeric','gt:0'],'reference'=>['nullable','string','max:150'],'allocations'=>['nullable','array'],'allocations.*'=>['nullable','numeric','min:0']]);$service->post($data,$r->user());return redirect()->route('payables.index')->with('success','Supplier payment posted successfully.');}public function ledger(Request $r,Supplier $supplier){abort_unless($supplier->company_id===$r->user()->company_id,404);$invoices=SupplierInvoice::where('supplier_id',$supplier->id)->get();$payments=SupplierPayment::where('supplier_id',$supplier->id)->get();return view('payables.ledger',compact('supplier','invoices','payments'));}public function aging(Request $r){$items=SupplierInvoice::with('supplier')->where('company_id',$r->user()->company_id)->where('balance_amount','>',0)->get();return view('payables.aging',compact('items'));}}
